with base as materialized (select comment_id, post_id, subreddit, score, n_replies, body, embedding,
  percent_rank() over (partition by post_id order by score) as spct
  from comments where length(body) >= 25 and embedding is not null),
c0 as materialized (select (row_number() over ())::int - 1 as cid, embedding as cen from (select embedding from base order by md5(comment_id) limit 7) s),
a0 as materialized (select b.comment_id, (select cid from c0 order by b.embedding <=> c0.cen limit 1) as cid from base b),
c1 as materialized (select a.cid, avg(b.embedding) as cen from a0 a join base b using (comment_id) group by a.cid),
a1 as materialized (select b.comment_id, (select cid from c1 order by b.embedding <=> c1.cen limit 1) as cid from base b),
c2 as materialized (select a.cid, avg(b.embedding) as cen from a1 a join base b using (comment_id) group by a.cid),
a2 as materialized (select b.comment_id, (select cid from c2 order by b.embedding <=> c2.cen limit 1) as cid from base b),
c3 as materialized (select a.cid, avg(b.embedding) as cen from a2 a join base b using (comment_id) group by a.cid),
a3 as materialized (select b.comment_id, (select cid from c3 order by b.embedding <=> c3.cen limit 1) as cid from base b),
c4 as materialized (select a.cid, avg(b.embedding) as cen from a3 a join base b using (comment_id) group by a.cid),
a4 as materialized (select b.comment_id, (select cid from c4 order by b.embedding <=> c4.cen limit 1) as cid from base b),
c5 as materialized (select a.cid, avg(b.embedding) as cen from a4 a join base b using (comment_id) group by a.cid),
a5 as materialized (select b.comment_id, (select cid from c5 order by b.embedding <=> c5.cen limit 1) as cid from base b),
c6 as materialized (select a.cid, avg(b.embedding) as cen from a5 a join base b using (comment_id) group by a.cid),
a6 as materialized (select b.comment_id, (select cid from c6 order by b.embedding <=> c6.cen limit 1) as cid from base b),
c7 as materialized (select a.cid, avg(b.embedding) as cen from a6 a join base b using (comment_id) group by a.cid),
a7 as materialized (select b.comment_id, (select cid from c7 order by b.embedding <=> c7.cen limit 1) as cid from base b),
c8 as materialized (select a.cid, avg(b.embedding) as cen from a7 a join base b using (comment_id) group by a.cid),
a8 as materialized (select b.comment_id, (select cid from c8 order by b.embedding <=> c8.cen limit 1) as cid from base b),
c9 as materialized (select a.cid, avg(b.embedding) as cen from a8 a join base b using (comment_id) group by a.cid),
a9 as materialized (select b.comment_id, (select cid from c9 order by b.embedding <=> c9.cen limit 1) as cid from base b),
c10 as materialized (select a.cid, avg(b.embedding) as cen from a9 a join base b using (comment_id) group by a.cid),
fin as materialized (select b.*, (select cid from c10 order by b.embedding <=> c10.cen limit 1) as cid from base b),
fd as materialized (select f.*, f.embedding <=> c.cen as dist from fin f join c10 c using (cid))
select cid, count(*) n,
 round(avg(dist)::numeric,3) cohesion,
 (select json_object_agg(subreddit, k) from (select subreddit, count(*) k from fd x where x.cid=fd.cid group by 1) q) subs,
 (select json_object_agg(post_id, k) from (select post_id, count(*) k from fd x where x.cid=fd.cid group by 1) q) posts,
 (select json_agg(t) from (select score, left(regexp_replace(body,'\s+',' ','g'),150) txt from fd x where x.cid=fd.cid order by dist limit 5) t) central,
 (select json_agg(t) from (select score, left(regexp_replace(body,'\s+',' ','g'),150) txt from fd x where x.cid=fd.cid order by score desc limit 3) t) top,
 (select json_agg(t) from (select n_replies r, score, left(regexp_replace(body,'\s+',' ','g'),130) txt from fd x where x.cid=fd.cid and n_replies>=2 order by ln(1+n_replies)*(1-spct) desc limit 2) t) contested
from fd group by cid order by n desc